const listServersDueForPatchCheck = `-- name: ListServersDueForPatchCheck :many
SELECT s.id, s.workspace_id, s.name, s.facts
FROM servers s
WHERE s.status = 'online'
  AND NOT EXISTS (
      SELECT 1 FROM server_patch_runs r
      WHERE r.server_id = s.id AND r.created_at > now() - make_interval(secs => $1::float8)
  )
`

